import { escapeHtml } from '../../../engine/utils/escape-html';
import { DOCUMENT_CSS, DocumentShiftInfo, documentHeaderHtml, fmtTime, shiftDetailsHtml, staffCellHtml } from './adolphus-document';

/**
 * Pre-shift SHIFT ATTENDANCE SHEET (Adolphus Group template, owner design 2026-10-17). Generated by the worker
 * (`shift-report-scheduler.job.ts`) REPORT_AVAILABLE_BEFORE_MINUTES before the shift and rendered by the existing
 * Playwright pipeline. The QR is the real signed Shift QR from `AttendanceQrService` + `QrImageService`, embedded as a
 * base64 PNG — never a placeholder; it carries no account token. Ratings, confirmation and signatures are not part of
 * this before-shift document.
 */
export interface PreShiftReportStaffRow {
  name: string;
  staffRef?: string | null;
  roleName: string;
  /** This staff member's effective scheduled window (per-assignment period, falling back to the shift's). */
  scheduledStart: string;
  scheduledEnd: string;
  breakMinutes: number | null;
}

export interface PreShiftReportData extends DocumentShiftInfo {
  staff: PreShiftReportStaffRow[];
  qrPngBase64: string;
}

export function renderPreShiftReportHtml(data: PreShiftReportData): string {
  const tz = data.timezone;
  const rows = data.staff
    .map(
      (s) => `
      <tr>
        <td>${staffCellHtml(s.name, [s.staffRef, s.roleName].filter(Boolean).join(' · '))}</td>
        <td>${escapeHtml(fmtTime(s.scheduledStart, tz))}</td>
        <td>${escapeHtml(fmtTime(s.scheduledEnd, tz))}</td>
        <td>${s.breakMinutes != null ? `${s.breakMinutes} min` : '—'}</td>
      </tr>`,
    )
    .join('');

  return `<!doctype html>
<html>
<head>
<meta charset="utf-8">
<title>Shift attendance sheet — ${escapeHtml(data.venueName)}</title>
<style>
${DOCUMENT_CSS}
  .qr { width: 150px; border: 1px solid #E3E5E2; border-radius: 10px; background: #F6F7F5; padding: 10px; text-align: center; flex: none; }
  .qr img { width: 128px; height: 128px; display: block; margin: 0 auto 6px; }
  .qr b { display: block; font-size: 10px; letter-spacing: .3px; }
  .qr small { color: #8A8F8C; font-size: 8.5px; }
</style>
</head>
<body>
  ${documentHeaderHtml('Shift attendance sheet')}
  <section class="top">
    <div>${shiftDetailsHtml(data)}</div>
    <div class="qr">
      <img src="data:image/png;base64,${data.qrPngBase64}" alt="Shift QR code for clock in and clock out">
      <b>CLOCK IN / OUT</b>
      <small>System-generated code</small>
    </div>
  </section>
  <div class="summary">Before shift · ${data.staff.length} assigned staff · Scan the QR in the staff app to clock in or out</div>
  <table>
    <thead><tr><th style="width:44%">Assigned staff</th><th>Scheduled start</th><th>Scheduled finish</th><th>Planned break</th></tr></thead>
    <tbody>${rows || '<tr><td colspan="4" class="muted">No confirmed staff yet.</td></tr>'}</tbody>
  </table>
  <div class="note-line">Staff review and signatures are added only after the venue manager reviews and confirms the report.</div>
  <section class="bottom">
    <div>
      <h3>NOTES</h3>
      <p>${data.notes && data.notes.trim() ? escapeHtml(data.notes) : '<span class="muted">No shift notes.</span>'}</p>
      <p class="muted">The QR grants attendance access for this shift only.</p>
    </div>
    <div>
      <h3>BEFORE-SHIFT DOCUMENT</h3>
      <p>Use the QR above to clock in and clock out.</p>
      <p>Ratings, confirmation and signatures are not included yet.</p>
    </div>
  </section>
</body>
</html>`;
}
